@app.post("/calculate")
def calculate():
    d = save_draft(request.form)
    total = sum(b["amount"] for b in draft_bets(d))
    if total > summary()["remaining"]:
        return redirect(url_for(
            "home",
            msg=f"計算しました。合計{total:,}円です。本日の残り予算を超えています。"
        ))
    return redirect(url_for("home", msg=f"計算しました。合計 {total:,}円です。"))


@app.route("/analyze", methods=["GET", "POST"])
def analyze():
    course = request.values.get("course", "")
    race = to_int(request.values.get("race", ""), 0)
    mode = request.values.get("mode", "バランス")
    opts = "".join(
        f'<option {"selected" if c == course else ""}>{c}</option>'
        for c in NAR_COURSE_CODES
    )
    race_opts = "".join(
        f'<option value="{n}" {"selected" if n == race else ""}>{n}R</option>'
        for n in range(1, 13)
    )
    mode_opts = "".join(
        f'<option {"selected" if m == mode else ""}>{m}</option>'
        for m in ("堅め", "バランス", "穴狙い")
    )

    form = f"""<div class="card"><div class="title">オッズ取得・3点予想</div>
    <form method="post">
    <div class="two">
      <div><label>競馬場</label><select name="course"><option value="">選択してください</option>{opts}</select></div>
      <div><label>レース</label><select name="race"><option value="">選択</option>{race_opts}</select></div>
    </div><br>
    <div><label>予想モード</label><select name="mode">{mode_opts}</select></div><br>
    <button class="green">ワイドオッズ取得 → 3点予想</button>
    </form></div>"""

    auto_run = request.args.get("auto", "") == "1"

    if request.method == "GET" and not auto_run:
        return page(form, "オッズ・3点予想")

    if course not in NAR_COURSE_CODES or not (1 <= race <= 12):
        return page(form + '<div class="bad">競馬場とレース番号を選択してください。</div>', "オッズ・3点予想")

    try:
        wide_data = nar_get_wide_odds(course, race)
        horse_data = nar_get_horse_market(course, race)
    except Exception as exc:
        return page(
            form + f'<div class="bad">取得エラー：{html.escape(type(exc).__name__)} - {html.escape(str(exc))}</div>',
            "オッズ・3点予想"
        )

    if not wide_data:
        return page(
            form + '<div class="note">ワイドオッズを取得できませんでした。発売前・締切後・NAR側更新中の可能性があります。</div>',
            "オッズ・3点予想"
        )

    if not horse_data:
        return page(
            form + '<div class="note">単勝・複勝データを取得できませんでした。発売前などの可能性があります。</div>',
            "オッズ・3点予想"
        )

    result = evaluate_race_rank(horse_data, wide_data, mode, summary()["remaining"])
    save_pick(course, race, mode, result)
    recs = result["recommendations"][:3]
    allocation = allocate_amounts(result["grade"], recs, summary()["remaining"])
    amounts = allocation["amounts"]

    rec_rows = ""
    rec_cards = ""
    hidden = ""
    for idx, item in enumerate(recs, start=1):
        amount = amounts[idx - 1] if idx - 1 < len(amounts) else 0
        rec_rows += (
            f'<tr class="{"rank1" if idx == 1 else ""}><td>{idx}位</td>'
            f'<td><strong>{html.escape(item["combo"])}</strong></td>'
            f'<td>{html.escape(item["display"])}倍</td>'
            f'<td>{item["confidence"]}点</td>'
            f'<td>{item.get("priority_score", 0):.1f}</td>'
            f'<td>{item.get("ev_index", 0):.2f}<br><span class="small">{html.escape(item.get("ev_label",""))}</span></td>'
            f'<td>{amount:,}円</td></tr>'
        )
        rec_cards += (
            f'<div class="pick-card {"pick-rank-one" if idx == 1 else ""}>'
            f'<div class="pick-rank">{idx}位</div>'
            f'<div class="pick-combo">{html.escape(item["combo"])}</div>'
            f'<div class="pick-grid">'
            f'<div><span>オッズ</span><strong>{html.escape(item["display"])}倍</strong></div>'
            f'<div><span>候補評価</span><strong>{item["confidence"]}点</strong></div>'
            f'<div><span>優先度</span><strong>{item.get("priority_score", 0):.1f}</strong></div>'
            f'<div><span>参考EV</span><strong>{item.get("ev_index", 0):.2f}</strong><small>{html.escape(item.get("ev_label",""))}</small></div>'
            f'</div>'
            f'<div class="pick-amount">推奨額 <strong>{amount:,}円</strong></div>'
            f'</div>'
        )
        hidden += (
            f'<input type="hidden" name="wide{idx}" value="{html.escape(item["combo"])}">'
            f'<input type="hidden" name="odds{idx}" value="{item["low"]}">'
            f'<input type="hidden" name="amount{idx}" value="{amount or DEFAULT_BET}">'
        )

    reasons = "".join(f"<li>{html.escape(x)}</li>" for x in result["reasons"])
    all_rows = "".join(
        f"<tr><td>{html.escape(x['combo'])}</td><td>{html.escape(x['display'])}</td><td>{html.escape(str(x.get('popularity','')))}</td></tr>"
        for x in wide_data[:50]
    )

    result_html = f"""
    <div class="card">
      <div class="title">{html.escape(course)} {race}R　参考判定</div>
      <div class="grade">{html.escape(result["grade"])}</div>
      <div class="score">参考スコア {result["score"]} / 100</div>
      <ul>{reasons}</ul>
      <div class="small">※これは的中確率ではありません。市場オッズを使ったルールベース評価です。</div>
    </div>

    <div class="card">
      <div class="title">3点候補</div>
      <div class="pick-cards">{rec_cards or '<div class="note">候補を3点作れませんでした。</div>'}</div>
      {(('<div class="ok">' + html.escape(allocation["note"]) + '</div>') if allocation.get("all_positive") and allocation.get("note") else '')}
      {(('<div class="note">' + html.escape(allocation["note"]) + '</div>') if (not allocation.get("all_positive")) and allocation.get("note") and recs else '')}
      {"<form method='post' action='/apply_recommendations'>" + hidden +
       f"<input type='hidden' name='course' value='{html.escape(course)}'>"
       f"<input type='hidden' name='race' value='{race}R'>"
       f"<input type='hidden' name='mode' value='{html.escape(mode)}'>"
       "<button class='green'>この3点をホームへ入力</button></form>" if recs else ""}
    </div>

    <div class="card">
      <div class="title">取得したワイドオッズ（最大50組）</div>
      <div class="scroll"><table><tr><th>組合せ</th><th>オッズ</th><th>人気</th></tr>{all_rows}</table></div>
    </div>
    """

    return page(form + result_html, "オッズ・3点予想")


@app.post("/apply_recommendations")
def apply_recommendations():
    vals = {
        "course": request.form.get("course", ""),
        "race": request.form.get("race", ""),
        "mode": request.form.get("mode", "不明") or "不明",
    }
    for i in range(1, 4):
        vals[f"wide{i}"] = clean_combo(request.form.get(f"wide{i}", ""))
        vals[f"odds{i}"] = to_float(request.form.get(f"odds{i}", ""), 0.0)
        vals[f"amount{i}"] = max(100, to_int(request.form.get(f"amount{i}", ""), DEFAULT_BET)) if vals[f"wide{i}"] else 0
    write_draft(vals)
    return redirect(url_for("home", msg="3点候補を自動入力しました。下に合計購入額・想定払戻・1点的中時の損益を表示しています。"))


@app.post("/record")
def record():
    d = get_draft()
    bets = draft_bets(d)
    if not d or not bets:
        return redirect(url_for("home", msg="先に購入内容を計算してください。"))

    total = sum(b["amount"] for b in bets)
    if total > summary()["remaining"]:
        return redirect(url_for("home", msg="本日の残り予算を超えるため記録できません。"))

    bet_text = " / ".join(
        f"{b['combo']} {b['amount']}円 @{b['odds']}" for b in bets
    )

    with db() as con:
        con.execute("""
        INSERT INTO purchases(created_at,race_date,course,race,bets,total_bet,result,return_amount,mode)
        VALUES(?,?,?,?,?,?,?,?,?)
        """, (
            now().strftime("%Y-%m-%d %H:%M:%S"), today(),
            d.get("course") or "", d.get("race") or "",
            bet_text, total, "未確定", 0, d.get("mode") or "不明",
        ))

    return redirect(url_for("history", msg="購入記録を追加しました。レース終了後、この画面で「的中」または「ハズレ」を押すだけで成績が自動集計されます。"))


@app.get("/picks")
def picks():
    with db() as con:
        rows = con.execute(
            "SELECT * FROM picks WHERE race_date=? ORDER BY "
            "CASE grade WHEN 'S+' THEN 1 WHEN 'S' THEN 2 WHEN 'S-' THEN 3 WHEN 'A' THEN 4 ELSE 9 END,"
            "score DESC, id DESC",
            (today(),),
        ).fetchall()

    trs = ""
    for r in rows:
        trs += (
            f"<tr><td><strong>{html.escape(r['course'])} {html.escape(r['race'])}</strong></td>"
            f"<td>{html.escape(r['mode'])}</td><td><strong>{html.escape(r['grade'])}</strong></td>"
            f"<td>{r['score']}</td><td>{html.escape(r['candidate1'])}<br>{html.escape(r['candidate2'])}<br>{html.escape(r['candidate3'])}</td></tr>"
        )

    if not trs:
        trs = '<tr><td colspan="5">まだ勝負レース候補はありません。「オッズ・3点予想」で分析したS/A系レースがここに保存されます。</td></tr>'

    return page(
        f"""<div class="card"><div class="title">今日の勝負レース</div>
        <div class="scroll"><table><tr><th>レース</th><th>モード</th><th>判定</th><th>スコア</th><th>3点候補</th></tr>{trs}</table></div></div>""",
        "今日の勝負レース"
    )


@app.get("/history")
def history():
    msg = request.args.get("msg", "")
    with db() as con:
        rows = con.execute(
            "SELECT * FROM purchases ORDER BY id DESC LIMIT 200"
        ).fetchall()
        all_rows = con.execute(
            "SELECT * FROM purchases ORDER BY id DESC"
        ).fetchall()

    def make_stats(source):
        confirmed = [r for r in source if r["result"] in ("的中", "ハズレ")]
        hits = [r for r in confirmed if r["result"] == "的中"]
        pending = [r for r in source if r["result"] == "未確定"]

        bet = sum(int(r["total_bet"]) for r in confirmed)
        ret = sum(int(r["return_amount"]) for r in confirmed)
        profit = ret - bet
        hit_rate = (len(hits) / len(confirmed) * 100) if confirmed else 0.0
        recovery = (ret / bet * 100) if bet else 0.0

        return {
            "confirmed": len(confirmed),
            "hits": len(hits),
            "pending": len(pending),
            "bet": bet,
            "ret": ret,
            "profit": profit,
            "hit_rate": hit_rate,
            "recovery": recovery,
        }

    overall = make_stats(all_rows)
    today_rows = [r for r in all_rows if r["race_date"] == today()]
    today_stats = make_stats(today_rows)

    def stats_cards(title, s):
        return f"""
        <div class="card stats-card">
          <div class="title">{html.escape(title)}</div>
          <div class="stats-grid">
            <div><span>確定レース</span><strong>{s["confirmed"]}件</strong></div>
            <div><span>的中率</span><strong>{s["hit_rate"]:.1f}%</strong></div>
            <div><span>回収率</span><strong>{s["recovery"]:.1f}%</strong></div>
            <div><span>確定収支</span><strong>{s["profit"]:+,}円</strong></div>
            <div><span>総購入額</span><strong>{s["bet"]:,}円</strong></div>
            <div><span>総払戻額</span><strong>{s["ret"]:,}円</strong></div>
            <div><span>未確定</span><strong>{s["pending"]}件</strong></div>
          </div>
        </div>
        """

    trs = ""
    mobile_cards = ""
    for r in rows:
        profit = int(r["return_amount"]) - int(r["total_bet"]) if r["result"] in ("的中", "ハズレ") else None
        result_badge = "pending" if r["result"] == "未確定" else ("hit" if r["result"] == "的中" else "miss")

        trs += f"""<tr>
        <td>{html.escape(r['created_at'])}</td>
        <td>{html.escape(r['course'])} {html.escape(r['race'])}</td>
        <td>{html.escape(r['bets'])}</td>
        <td>{r['total_bet']:,}円</td>
        <td>{html.escape(r['result'])}</td>
        <td>{r['return_amount']:,}円</td>
        <td>{"未確定" if profit is None else f"{profit:+,}円"}</td>
        <td><form method="post" action="/result/{r['id']}" style="display:flex;gap:4px;min-width:270px">
          <input name="return_amount" inputmode="numeric" placeholder="払戻額">
          <button class="green" name="kind" value="hit">的中</button>
          <button class="red" name="kind" value="miss">ハズレ</button>
        </form></td></tr>"""

        if r["result"] == "未確定":
            result_form = f"""
            <form method="post" action="/result/{r['id']}" class="history-result-form">
              <input name="return_amount" inputmode="numeric" placeholder="的中時の払戻額">
              <div class="history-result-buttons">
                <button class="green" name="kind" value="hit">的中で記録</button>
                <button class="red" name="kind" value="miss">ハズレで記録</button>
              </div>
            </form>
            """
        else:
            result_form = f"""
            <div class="history-final">
              払戻 <strong>{r['return_amount']:,}円</strong>　
              収支 <strong>{"未確定" if profit is None else f"{profit:+,}円"}</strong>
            </div>
            """

        mobile_cards += f"""
        <div class="history-card">
          <div class="history-card-head">
            <div>
              <div class="history-race">{html.escape(r['course'])} {html.escape(r['race'])}</div>
              <div class="small">{html.escape(r['created_at'])}</div>
            </div>
            <span class="result-badge {result_badge}">{html.escape(r['result'])}</span>
          </div>
          <div class="history-bets">{html.escape(r['bets'])}</div>
          <div class="history-mini-grid">
            <div><span>購入額</span><strong>{r['total_bet']:,}円</strong></div>
            <div><span>払戻額</span><strong>{r['return_amount']:,}円</strong></div>
          </div>
          {result_form}
        </div>
        """

    if not trs:
        trs = '<tr><td colspan="8">履歴はまだありません。</td></tr>'
        mobile_cards = '<div class="note">履歴はまだありません。</div>'

    return page(
        (f'<div class="ok">{html.escape(msg)}</div>' if msg else "")
        + stats_cards("本日の成績", today_stats)
        + stats_cards("通算成績", overall)
        + f"""<div class="card"><div class="title">成績履歴</div>
        <div class="mobile-history">{mobile_cards}</div>
        <div class="desktop-history scroll"><table>
        <tr><th>日時</th><th>レース</th><th>買い目</th><th>購入</th><th>結果</th><th>払戻</th><th>収支</th><th>結果入力</th></tr>
        {trs}</table></div></div>""",
        "成績履歴"
    )


@app.get("/analytics")
def analytics():
    with db() as con:
        rows = con.execute(
            "SELECT * FROM purchases WHERE result IN ('的中','ハズレ') ORDER BY race_date DESC,id DESC"
        ).fetchall()

    def aggregate(key_fn):
        groups = {}
        for r in rows:
            key = key_fn(r)
            if not key:
                key = "不明"
            g = groups.setdefault(key, {
                "races": 0, "hits": 0, "bet": 0, "ret": 0
            })
            g["races"] += 1
            if r["result"] == "的中":
                g["hits"] += 1
            g["bet"] += int(r["total_bet"])
            g["ret"] += int(r["return_amount"])

        result = []
        for key, g in groups.items():
            g["key"] = key
            g["profit"] = g["ret"] - g["bet"]
            g["hit_rate"] = (g["hits"] / g["races"] * 100) if g["races"] else 0.0
            g["recovery"] = (g["ret"] / g["bet"] * 100) if g["bet"] else 0.0
            result.append(g)
        return result

    # YYYY-MM 単位
    monthly = aggregate(lambda r: (r["race_date"] or "")[:7])
    monthly.sort(key=lambda x: x["key"], reverse=True)

    by_course = aggregate(lambda r: r["course"] or "不明")
    by_course.sort(key=lambda x: (x["recovery"], x["profit"]), reverse=True)

    by_mode = aggregate(lambda r: r["mode"] or "不明")
    by_mode.sort(key=lambda x: (x["recovery"], x["profit"]), reverse=True)

    def table_block(title, items, key_label):
        if not items:
            return f'<div class="card"><div class="title">{html.escape(title)}</div><div class="note">確定済みの成績データがまだありません。</div></div>'

        desktop_rows = ""
        mobile_cards = ""
        for g in items:
            desktop_rows += (
                f"<tr><td><strong>{html.escape(str(g['key']))}</strong></td>"
                f"<td>{g['races']}件</td><td>{g['hit_rate']:.1f}%</td>"
                f"<td>{g['recovery']:.1f}%</td><td>{g['bet']:,}円</td>"
                f"<td>{g['ret']:,}円</td><td>{g['profit']:+,}円</td></tr>"
            )
            mobile_cards += f"""
            <div class="analysis-card">
              <div class="analysis-key">{html.escape(str(g["key"]))}</div>
              <div class="analysis-grid">
                <div><span>確定レース</span><strong>{g["races"]}件</strong></div>
                <div><span>的中率</span><strong>{g["hit_rate"]:.1f}%</strong></div>
                <div><span>回収率</span><strong>{g["recovery"]:.1f}%</strong></div>
                <div><span>収支</span><strong>{g["profit"]:+,}円</strong></div>
                <div><span>購入額</span><strong>{g["bet"]:,}円</strong></div>
                <div><span>払戻額</span><strong>{g["ret"]:,}円</strong></div>
              </div>
            </div>
            """

        return f"""
        <div class="card">
          <div class="title">{html.escape(title)}</div>
          <div class="mobile-analysis">{mobile_cards}</div>
          <div class="desktop-analysis scroll">
            <table>
              <tr><th>{html.escape(key_label)}</th><th>確定</th><th>的中率</th><th>回収率</th><th>購入額</th><th>払戻額</th><th>収支</th></tr>
              {desktop_rows}
            </table>
          </div>
        </div>
        """

    # ベスト指標（データがある場合のみ）
    best_course = by_course[0] if by_course else None
    best_mode = by_mode[0] if by_mode else None

    highlights = ""
    if best_course or best_mode:
        highlights = '<div class="card"><div class="title">成績ハイライト</div><div class="highlight-grid">'
        if best_course:
            highlights += (
                f'<div><span>回収率トップ競馬場</span><strong>{html.escape(str(best_course["key"]))}</strong>'
                f'<small>回収率 {best_course["recovery"]:.1f}% / 収支 {best_course["profit"]:+,}円</small></div>'
            )
        if best_mode:
            highlights += (
                f'<div><span>回収率トップ予想モード</span><strong>{html.escape(str(best_mode["key"]))}</strong>'
                f'<small>回収率 {best_mode["recovery"]:.1f}% / 収支 {best_mode["profit"]:+,}円</small></div>'
            )
        highlights += "</div></div>"

    body = (
        highlights
        + table_block("月別成績", monthly, "月")
        + table_block("競馬場別成績", by_course, "競馬場")
        + table_block("予想モード別成績", by_mode, "予想モード")
        + '<div class="note">回収率や的中率は確定済みの購入記録だけを集計します。データ件数が少ない段階では参考値としてご覧ください。</div>'
    )
    return page(body, "成績分析")


@app.post("/result/<int:pid>")
def result(pid):
    kind = request.form.get("kind")
    if kind == "hit":
        ret = max(0, to_int(request.form.get("return_amount"), 0))
        result_text = "的中"
        if ret <= 0:
            return redirect(url_for("history", msg="的中の場合は払戻額を入力してください。"))
    else:
        ret = 0
        result_text = "ハズレ"

    with db() as con:
        con.execute(
            "UPDATE purchases SET result=?,return_amount=? WHERE id=?",
            (result_text, ret, pid),
        )
    return redirect(url_for("history", msg=f"{result_text}として更新しました。"))


